'use strict';

const _get = require('lodash/get');
const _setWith = require('lodash/setWith');
const cookie = require('cookie');

/**
 * Обфусцирует чувствительные куки в http заголовке.
 *
 * Пример подключения:
 *   require('@yandex-int/yandex-logger/middleware/secure-cookie')({
 *       field: 'req.headers.cookie',
 *       cookies: ['secret_key']
 *   });
 *
 * Пример лога:
 *   logger.info({ req: { headers: { cookie: 'user_id=123;secret_key=2929439829;foo=bar' }}}
 *
 *   output:
 *      {"req":{"headers":{"cookie":"user_id=123;secret_key=29294XXXXX;foo=bar"}}}
 *
 * @param {Object} [config]
 * @returns {Function}
 * @see https://wiki.yandex-team.ru/logfeller/security/
 */
module.exports = config => {
    config = config || {};

    let field = config.field || 'req.headers.cookie';
    let cookies = config.cookies || [];
    let secureValue = config.secureValue || defaultSecureValue;

    /**
     * @param {Object} record
     * @returns {undefined}
     */
    return record => {
        let value = _get(record, field);
        let newValue = value;

        if (typeof value === 'object' && value !== null) {
            newValue = secureCookieObject(value, cookies, secureValue);
        }

        if (typeof value === 'string') {
            newValue = secureCookieString(value, cookies, secureValue);
        }

        if (newValue !== value) {
            _setWith(record, field, newValue, value => {
                return Object.assign({}, value);
            });
        }
    };
};

/**
 * @param {Object} cookies
 * @param {String[]} names
 * @param {Function} secureValue
 * @returns {Object}
 */
function secureCookieObject(cookies, names, secureValue) {
    // Не меняем исходный объект
    cookies = Object.assign({}, cookies);

    for (let name of names) {
        let value = cookies[name];

        if (typeof value === 'string') {
            cookies[name] = secureValue(value);
        }
    }

    return cookies;
}

/**
 * @param {String} header
 * @param {String[]} names
 * @param {Function} secureValue
 * @returns {String}
 */
function secureCookieString(header, names, secureValue) {
    let cookies = cookie.parse(header);
    cookies = secureCookieObject(cookies, names, secureValue);

    let keys = Object.keys(cookies);
    let parts = [];

    for (let name of keys) {
        let value = encodeURIComponent(cookies[name]);
        parts.push(`${name}=${value}`);
    }

    return parts.join('; ');
}

/**
 * @param {String} value
 * @returns {String}
 */
function defaultSecureValue(value) {
    let len = value.length;
    let center = Math.floor(len / 2);
    return value.slice(0, center) + 'X'.repeat(len - center);
}
